PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : CONST INT := 10;
    HighLimit : CONST INT := 90;
    PumpTimer : TON;
END_VAR

IF Level <= LowLimit THEN
    PumpIn := TRUE;
    PumpTimer(IN := TRUE, PT := T#0s);
    ValveOut := FALSE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    PumpTimer(IN := FALSE, PT := T#0s);
    ValveOut := TRUE;
ELSE
    PumpIn := PumpTimer.Q;
    ValveOut := FALSE;
END_IF;

// Safety check: PumpIn should never be TRUE when Level >= HighLimit
IF Level >= HighLimit AND PumpIn THEN
    PumpIn := FALSE;
END_IF;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpTimer : TON;
    ValveTimer : TON;
    LowLimit : INT := 10;
    HighLimit : INT := 90;
END_VAR

// Check if level is at or above the high limit
IF Level >= HighLimit THEN
    PumpIn := FALSE; // Safety rule: PumpIn must never run while the level is at or above the high limit
    ValveOut := TRUE; // Open outlet valve to prevent overflow
    PumpTimer(IN := FALSE); // Reset pump timer
    ValveTimer(IN := TRUE, PT := T#5s); // Start valve timer for 5 seconds
ELSIF Level <= LowLimit THEN
    PumpIn := TRUE; // Turn on inlet pump
    ValveOut := FALSE; // Close outlet valve
    PumpTimer(IN := TRUE, PT := T#5s); // Start pump timer for 5 seconds
    ValveTimer(IN := FALSE);
ELSE
    PumpIn := FALSE; // Turn off inlet pump
    ValveOut := FALSE; // Close outlet valve
    PumpTimer(IN := FALSE); // Reset pump timer
    ValveTimer(IN := FALSE);
END_IF;

// Hysteresis logic based on timer output
IF PumpTimer.Q AND NOT ValveTimer.Q THEN
    PumpIn := TRUE;
END_IF;

IF NOT PumpTimer.Q AND ValveTimer.Q THEN
    ValveOut := TRUE;
END_IF;
END_PROGRAM

