    END_IF;
ELSE
    IF OpenB_Cmd THEN
        DoorA := FALSE;
        DoorB := TRUE;
        DoorATimer(IN := FALSE, PT := T#0s);
        DoorBTimer(IN := TRUE, PT := T#0s);
    ELSE
        IF NOT DoorBTimer.Q THEN
            DoorA := FALSE;
            DoorB := FALSE;
            DoorATimer(IN := FALSE, PT := T#0s);
            DoorBTimer(IN := FALSE, PT := T#0s);
        END_IF;
    END_IF;
END_IF;

LastDoorA := DoorA;
LastDoorB := DoorB;
