PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    StartTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault, PT := T#0s);

IF StartTimer.Q THEN
    Running := TRUE;
END_IF;

Conveyor := Running AND GuardClosed AND NOT Fault;

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
END_IF;

END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    GuardTimer : TON;
END_VAR

CONST
    GuardDelay : TIME := T#0.5s;
END_CONST

// Start button press logic
IF StartPB AND GuardClosed AND NOT Fault THEN
    GuardTimer(IN := TRUE, PT := GuardDelay);
END_IF;

// Check for guard delay expiration
IF GuardTimer.Q THEN
    Running := TRUE;
END_IF;

// Stop button press logic
IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
END_IF;

// Assign output based on running state
Conveyor := Running;
END_PROGRAM

