    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    StartTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault, PT := T#0s);

IF StartTimer.Q THEN
    Running := TRUE;
END_IF;

Conveyor := Running AND NOT StopPB AND GuardClosed AND NOT Fault;

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
END_IF;
END_PROGRAM

