PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    T1, T2, T3 : TON;
END_VAR

// Initialize state to the first phase
State := 0;

// Main loop
WHILE TRUE DO
    CASE State OF
        0: // NS green / EW red
            NS_G := TRUE;
            NS_Y := FALSE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
            T1(IN := NS_G OR NS_Y, PT := T#2s);
            IF T1.Q THEN
                State := 1;
            END_IF;

        1: // NS yellow / EW red
            NS_G := FALSE;
            NS_Y := TRUE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
            T2(IN := NS_Y, PT := T#1s);
            IF T2.Q THEN
                State := 2;
            END_IF;

        2: // all-red clearance
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
            T3(IN := TRUE, PT := T#1s);
            IF T3.Q THEN
                State := 3;
            END_IF;

        3: // EW green / NS red
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := TRUE;
            EW_Y := FALSE;
            EW_R := FALSE;
            T1(IN := EW_G OR EW_Y, PT := T#2s);
            IF T1.Q THEN
                State := 4;
            END_IF;

        4: // EW yellow / NS red
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := TRUE;
            EW_R := FALSE;
            T2(IN := EW_Y, PT := T#1s);
            IF T2.Q THEN
                State := 5;
            END_IF;

        5: // all-red clearance
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
            T3(IN := TRUE, PT := T#1s);
            IF T3.Q THEN
                State := 0;
            END_IF;
    END_CASE;
END_WHILE
END_PROGRAM

PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R : BOOL;
    EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    T_Green : TON;
    T_ Yellow : TON;
    T_AllRed : TON;
END_VAR

T_Green(IN := State IN {0, 3}, PT := T#2s);
T_ Yellow(IN := State IN {1, 4}, PT := T#1s);
T_AllRed(IN := State IN {2, 5}, PT := T#1s);

CASE State OF
    0:
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    1:
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    2:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    3:
        NS_G := FALSE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := TRUE;
    4:
        NS_G := FALSE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := TRUE;
    5:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
END_CASE;

IF T_Green.Q THEN
    State := State + 1;
END_IF;

IF T_ Yellow.Q AND NOT T_Green.Q THEN
    State := State + 1;
END_IF;

IF T_AllRed.Q AND NOT (T_Green.Q OR T_ Yellow.Q) THEN
    State := State + 1;
END_IF;

State := State MOD 6;
END_PROGRAM

PROGRAM intersection
VAR
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
    State : INT := 0;
    NS_green : TON;
    NS_yellow : TON;
    NS_allred : TON;
    EW_green : TON;
    EW_yellow : TON;
    EW_allred : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

NS_G := FALSE;
NS_Y := FALSE;
NS_R := TRUE;
EW_G := FALSE;
