PROGRAM elevator
VAR
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
    MotorUp : BOOL;
    MotorDown : BOOL;
    State : INT(0..3);
    MoveTimer : TON;
END_VAR

CASE State OF
    0: // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
            MotorUp := TRUE;
            MotorDown := FALSE;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    1: // Moving-up
        IF AtTop OR Not DoorClosed THEN
            State := 2;
            MotorUp := FALSE;
            MotorDown := FALSE;
        ELSE
            MotorUp := TRUE;
            MotorDown := FALSE;
        END_IF;

    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
            MotorUp := FALSE;
            MotorDown := TRUE;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    3: // Moving-down
        IF AtBottom OR Not DoorClosed THEN
            State := 0;
            MotorUp := FALSE;
            MotorDown := FALSE;
        ELSE
            MotorUp := FALSE;
            MotorDown := TRUE;
        END_IF;
END_CASE

// Ensure motors do not run together
MotorUp := MotorUp AND NOT MotorDown;
MotorDown := MotorDown AND NOT MotorUp;

END_PROGRAM

