    LVL_LOW : CONST INT := 5;
    TEMP_SET : CONST INT := 100;
    PT_REACT : CONST TIME := T#3s;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

// Safety checks
IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
            FillTimer(IN := TRUE, PT := T#0s);
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

        IF Level >= LVL_HIGH OR NOT StartBatch THEN
            State := 2;
            FillValve := FALSE;
            FillTimer(IN := FALSE, PT := T#0s);
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF Temp >= TEMP_SET THEN
            State := 3;
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF FillTimer.Q AND DrainTimer.Q THEN
            State := 4;
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;

        IF Level <= LVL_LOW OR NOT StartBatch THEN
            State := 0;
            DrainValve := FALSE;
            DrainTimer(IN := FALSE, PT := T#0s);
        END_IF;
END_CASE;

// Timers
FillTimer(IN := StartBatch AND Level < LVL_HIGH, PT := T#0s);
DrainTimer(IN := Level > LVL_LOW, PT := T#0s);

END_PROGRAM

