        CarGreen := FALSE;
        CarYellow := FALSE;
        CarRed := TRUE;
        PedWalk := TRUE;

        IF WalkTimer.Q THEN
            State := 0;
        END_IF;

        WalkTimer(IN := TRUE, PT := PT_WALK);
