        Ignition := TRUE;
        IF IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
Fuel := Fuel AND Fan;
Ignition := Ignition AND Fuel;
