PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    PumpsRunning : BOOL := FALSE;
END_VAR

// Edge detection for demand
PrevDemand := Demand;

// Safety check for emergency stop
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    Lead := 0; // Reset lead pump
    PrevDemand := FALSE; // Reset previous demand state
    PumpsRunning := FALSE; // Reset running state
ELSE
    // Normal operation
    IF Demand AND NOT PrevDemand THEN
        // Demand has started
        PumpsRunning := TRUE;
    ELSIF NOT Demand AND PrevDemand THEN
        // Demand has ended, switch lead pump
        Lead := 1 - Lead;
        PumpsRunning := TRUE;
    ELSE
        // Demand remains the same or EStop is active
        PumpsRunning := FALSE;
    END_IF;

    // Assign output based on lead pump and demand
    Pump1 := (Lead = 0) AND PumpsRunning;
    Pump2 := (Lead = 1) AND PumpsRunning;
END_IF;
END_PROGRAM

