    T1 : TON;
END_VAR

T1(IN := NOT EStop AND Demand, PT := T#1s);

Pump1 := FALSE;
Pump2 := FALSE;

IF EStop THEN
    Lead := 0;
    PrevDemand := FALSE;
ELSE
    IF Demand THEN
        IF NOT PrevDemand THEN
            Lead := 1 - Lead;
        END_IF;
        PrevDemand := TRUE;
    ELSE
        PrevDemand := FALSE;
    END_IF;

    CASE Lead OF
        0: 
            Pump1 := TRUE;
        1: 
            Pump2 := TRUE;
    END_CASE;
END_IF;

END_PROGRAM

