END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    DemandTimer : TON;
END_VAR

Pump1 := FALSE;
Pump2 := FALSE;

IF NOT EStop THEN
    // Emergency stop activated, stop both pumps
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    DemandTimer(IN := Demand AND NOT PrevDemand, PT := T#1s);

    IF DemandTimer.Q THEN
        DemandTimer(IN := FALSE, PT := T#1s);

        IF Lead = 0 THEN
            Pump1 := TRUE;
            Pump2 := FALSE;
            Lead := 1;
        ELSE
            Pump1 := FALSE;
            Pump2 := TRUE;
            Lead := 0;
        END_IF;
    END_IF;
END_IF;

