IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Demand AND NOT PrevDemand THEN
        Lead := 1 - Lead;
    END_IF;

    CASE Lead OF
        0 :
            Pump1 := Demand;
            Pump2 := FALSE;
        1 :
            Pump1 := FALSE;
            Pump2 := Demand;
