// Update previous demand state for edge detection
PrevDemand := Demand;

// Check for emergency stop
IF NOT EStop THEN
    TmpPump1 := FALSE;
    TmpPump2 := FALSE;
END_IF

// Check for falling edge of demand to switch lead
IF NOT Demand AND PrevDemand THEN
    Lead := 1 - Lead; // Toggle lead
END_IF

// Assign pumps based on lead and demand
CASE Lead OF
    0:
        IF Demand THEN
            TmpPump1 := TRUE;
            TmpPump2 := FALSE;
        ELSE
            TmpPump1 := FALSE;
            TmpPump2 := FALSE;
        END_IF;
    1:
        IF Demand THEN
            TmpPump1 := FALSE;
            TmpPump2 := TRUE;
        ELSE
            TmpPump1 := FALSE;
            TmpPump2 := FALSE;
        END_IF;
END_CASE

// Apply outputs
