PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    PumpsRunning : BOOL := FALSE;
END_VAR

PumpsRunning := Pump1 OR Pump2;

// Update PrevDemand for edge detection
PrevDemand := Demand;

// Check for falling edge of Demand
IF NOT Demand AND PrevDemand THEN
    // Toggle Lead on demand end
    Lead := 1 - Lead;
END_IF;

// Ensure only one pump runs at a time
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    CASE Lead OF
        0 :
            Pump1 := Demand AND NOT PumpsRunning;
            Pump2 := FALSE;
        1 :
            Pump1 := FALSE;
            Pump2 := Demand AND NOT PumpsRunning;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_CASE;
END_IF;
END_PROGRAM

PROGRAM pump_alt
