PUMPTimer(IN := NOT(EStop) AND Demand, PT := T#0s);

IF EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    Lead := 0;
    PrevDemand := FALSE;
ELSIF NOT(Demand) AND PrevDemand THEN
    Lead := 1 - Lead;
END_IF;

PrevDemand := Demand;

CASE Lead OF
    0 :
        Pump1 := PUMPTimer.Q;
        Pump2 := NOT(PUMPTimer.Q);
    1 :
        Pump1 := NOT(PUMPTimer.Q);
        Pump2 := PUMPTimer.Q;
    ELSE
        Pump1 := FALSE;
