        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF T3_1.Q THEN
            State := 2;
        END_IF;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF T3_2.Q THEN
            State := 3;
        END_IF;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF EStop OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

IF EStop OR StopPB THEN
    State := 0;
END_IF;
END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR

VAR_OUTPUT
    Done : BOOL;
    Count : INT := 0;
END_VAR

VAR_INTERNAL
    PrevTrigger : BOOL := FALSE;
END_VAR

-- Update PrevTrigger for edge detection
PrevTrigger := Trigger;

-- Handle Reset
IF Reset THEN
    Count := 0;
    Done := FALSE;
END_IF;

-- Increment Count on rising edge of Trigger
IF NOT PrevTrigger AND Trigger THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
END_IF;

-- Assert Done when Count reaches 3
IF Count = 3 THEN
    Done := TRUE;
END_IF;
END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR

VAR_OUTPUT
    Done : BOOL;
    Count : INT := 0;
    PrevTrigger : BOOL := FALSE;
END_VAR

VAR
    Target : CONST INT := 3;
    CountIncremented : BOOL := FALSE;
END_VAR

-- Edge detection for Trigger
IF Trigger AND NOT PrevTrigger THEN
    CountIncremented := TRUE;
END_IF;

PrevTrigger := Trigger;

-- Increment count if edge detected and reset not active
IF CountIncremented AND NOT Reset THEN
    IF Count < Target THEN
        Count := Count + 1;
    END_IF;
END_IF;

-- Check if done
Done := Count = Target;

-- Reset count if Reset is active
IF Reset THEN
    Count := 0;
    Done := FALSE;
END_IF;

END_PROGRAM

